/** Changelog: comes from src/generated/changelog.json (generated by scripts/changelog.mjs at build time). */
import data from "../generated/changelog.json";
import { lang, locale, type Lang } from "../i18n";

/** A translated commit (src/i18n/changelog/<language>.json): only what is translated. */
export interface CommitText {
  subject?: string;
  body?: string;
}

export interface ChangeCommit {
  hash: string;
  short: string;
  date: string;
  subject: string;
  body: string;
  /** Translations per language (gathered by scripts/changelog.mjs); what is missing is shown in Spanish. */
  tr?: Partial<Record<Exclude<Lang, "es">, CommitText>>;
}

export interface ChangeVersion {
  /** null = commits that don't belong to any version yet (development build). */
  version: string | null;
  date: string | null;
  released: boolean;
  commits: ChangeCommit[];
}

export const CHANGELOG: ChangeVersion[] = (data as { versions: ChangeVersion[] }).versions;

/** Subject and body of a commit in a language (the current one by default); whatever isn't translated, in Spanish. */
export function commitText(c: ChangeCommit, l: Lang = lang()): { subject: string; body: string } {
  const tr = l === "es" ? undefined : c.tr?.[l];
  return { subject: tr?.subject ?? c.subject, body: c.body ? (tr?.body ?? c.body) : "" };
}

/** "0.10.2" > "0.9.9": compares numbers, not text. */
export function cmpVersion(a: string, b: string): number {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) - (pb[i] ?? 0);
  return 0;
}

/**
 * Versions between `from` (exclusive: what changed *after* it) and `to` (inclusive), from newest
 * to oldest. Without `from`, from the beginning; without `to`, up to the latest (includes what is
 * unpublished). So "from 0.1.0 to 0.3.0" is what 0.3.0 brings relative to 0.1.0.
 */
export function between(list: ChangeVersion[], from?: string, to?: string): ChangeVersion[] {
  return list.filter((v) => {
    if (v.version === null) return !to;
    if (from && cmpVersion(v.version, from) <= 0) return false;
    if (to && cmpVersion(v.version, to) > 0) return false;
    return true;
  });
}

/** Short date in the interface language's format. */
export const fmtDate = (iso: string | null) =>
  iso ? new Date(iso).toLocaleDateString(locale(), { day: "2-digit", month: "2-digit", year: "numeric" }) : "";
